import { SITE_NAME } from '@/lib/site-title';

/**
 * #171: the site-wide social preview image, generated by `src/app/opengraph-image.tsx`.
 *
 * Kept free of `next/og` so a page layout can name the fallback without bundling the
 * image renderer. A segment that sets its own `openGraph` replaces the root one whole,
 * so the root file-based image does not reach it; such a segment uses this path instead.
 */
export const DEFAULT_OG_IMAGE_PATH = '/opengraph-image';

export const DEFAULT_OG_IMAGE_SIZE = { width: 1200, height: 630 } as const;

export const DEFAULT_OG_IMAGE_ALT = `${SITE_NAME} - Cook from your fridge, waste nothing`;
